const fs = require('node:fs'), cp = require('node:child_process'), assert = require('node:assert/strict');
const {chromium} = require('<PLAYWRIGHT_MODULE>');
const root = '<EASYSTUD_SOURCE_ROOT>';
const runId = 'codex1-k1680-tail-f25r-native', out = __dirname;
const ps = (file, args) => cp.execFileSync('powershell.exe', ['-NoProfile', '-File', '<ORCHESTRATION_SCRIPTS>/' + file, ...args], {encoding: 'utf8'});
const css = file => fs.readFileSync(file, 'utf8').replace(/url\((["']?)(\.\.?\/[^)"']+)\1\)/g,
    (match, quote, relative) => 'url("' + new URL(relative, 'http://localhost:8051/local/groupimport/styles/student-management.css').href + '")');
async function settle(locator) {
    await locator.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(r)))));
    await locator.evaluate(async node => {
        const animations = [...node.getAnimations({subtree:true})];
        for (let n = node; n; n = n.parentElement) animations.push(...n.getAnimations());
        await Promise.all(animations.filter(a => Number.isFinite(a.effect.getTiming().iterations)).map(a => a.finished.catch(() => {})));
    });
}
async function measure(locator){return locator.evaluate(n=>{const m=n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return {width:r.width,height:r.height,padding:s.padding,radius:s.borderRadius,color:s.color,background:s.backgroundColor,border:s.border,fontSize:s.fontSize,lineHeight:s.lineHeight,maxHeight:s.maxHeight,scrollHeight:n.scrollHeight};};return {frame:m(n),parts:[...n.querySelectorAll('.local-groupimport-easystud__filters,.local-groupimport-easystud-advanced-filters,.local-groupimport-easystud-create-card,.fa,h3,p')].filter(n=>n.getClientRects().length).map(n=>({class:n.className,...m(n)}))};});}

(async () => {
    const result = {passed: false, rows: [], errors: [], runtimeFilesChanged: false};
    let lease = false, created = false, browser, page;
    try {
        ps('Acquire-EasyEduResourceLease.ps1', ['-Resource', 'moodle51-perf', '-ProjectNamespace', 'easystud', '-RunId', runId,
            '-Repository', root, '-Purpose', 'K16-80 disclosures exact native CSS parity, restored synthetic fixture', '-LeaseSeconds', '900', '-OwnerPid', String(process.pid)]);
        lease = true;
        const fixture = JSON.parse(cp.execFileSync('<PHP_BINARY>', [out + '/fixture.php', 'create'], {encoding: 'utf8'}));
        created = true; result.course = fixture.courseid;
        browser = await chromium.launch({headless: true, executablePath: '<CHROME_EXECUTABLE>'});
        for (const locale of ['fr', 'en']) for (const width of [1600, 390]) {
            const context = await browser.newContext({
                viewport: {width, height: 1000}, hasTouch: width === 390, reducedMotion: 'reduce'});
            page = await context.newPage();
            page.setDefaultTimeout(20000);
            page.on('pageerror', e => result.errors.push(e.message));
            page.on('console', m => {if (m.type() === 'error') result.errors.push(m.text());});
            await page.goto('http://localhost:8051/login/index.php?lang='+locale);await page.locator('#username').fill(fixture.username);await page.locator('#password').fill(fixture.password);await Promise.all([page.waitForURL(url=>!url.pathname.includes('/login/'),{waitUntil:'domcontentloaded',timeout:30000}) , page.locator('#loginbtn').click()]);
            const response = await page.goto('http://localhost:8051/local/groupimport/manage.php?id=' + fixture.courseid + '&lang=' + locale,
                {waitUntil: 'domcontentloaded', timeout: 180000});
            assert.equal(response.status(), 200);
            await page.waitForFunction(() => {
                const r = document.querySelector('#local-groupimport-easystud');
                return r?.dataset.easystudManagerInitialised === '1' && !r.classList.contains('is-action-busy') && !r.classList.contains('local-groupimport-easystud--booting');
            }, null, {timeout: 180000});
            const both = page.locator('[data-easystud-layout-mode="both"]'); if (await both.isVisible()) await both.click();
            if (width < 1024) await page.locator('[data-easystud-mobile-view="participants"]').click();
            await page.evaluate(() => {
                document.querySelectorAll('link[rel="stylesheet"]').forEach(n => {if (/\/local\/groupimport\/styles\//.test(n.href)) n.disabled = true;});
            });
            const style = await page.addStyleTag({content: css(out + '/before-student-management.css')});
            await page.addStyleTag({content: '.codex1-range-probe::before {content:none!important;}'});
            await page.evaluate(() => document.fonts.ready);
            const filterToggle=page.locator('[data-easystud-advanced-filters-toggle]:visible').first();await filterToggle.waitFor();if(await filterToggle.getAttribute('aria-expanded')!=='true')await filterToggle.click();await page.locator('.local-groupimport-easystud-advanced-filters.is-expanded:visible').first().waitFor();
            const panel=page.locator('.local-groupimport-easystud__panel > .card-body:visible').first();await panel.waitFor();
            for(const phase of ['before','after']){await style.evaluate((n,t)=>{n.textContent=t;},css(phase==='before'?out+'/before-student-management.css':root+'/styles/student-management.css'));await settle(panel);result.rows.push({kind:'workspace-shell',locale,width,phase,measurement:await measure(panel)});}
            await page.goto('http://localhost:8051/local/groupimport/index.php?id='+fixture.courseid+'&lang='+locale,{waitUntil:'domcontentloaded'});
            const form=page.locator('form.mform');await form.waitFor();
            await Promise.all([page.waitForNavigation({waitUntil:'domcontentloaded',timeout:180000}),form.evaluate((n,id)=>{n.querySelector('[name="importfile"]').value=String(id);HTMLFormElement.prototype.submit.call(n);},fixture.draftitemid)]);
            const search=page.locator('[data-local-groupimport-preview-search]');await search.waitFor({state:'visible',timeout:180000});await page.waitForFunction(()=>{const input=document.querySelector('[data-local-groupimport-preview-search]'),root=input?.closest('.local-groupimport-import');return root?.getAttribute(root.dataset.easyeduLoadingReadyAttribute||'data-easyedu-loading-ready')==='1';},null,{timeout:180000});await search.fill('no-matching-entry-'+fixture.courseid);
            const empty=page.locator('[data-local-groupimport-preview-empty]:visible');await empty.waitFor();
            await page.evaluate(()=>document.querySelectorAll('link[rel="stylesheet"]').forEach(n=>{if(/\/local\/groupimport\/styles\//.test(n.href))n.disabled=true;}));
            const massStyle=await page.addStyleTag({content:css(out+'/before-mass-import.css')});await page.evaluate(()=>document.fonts.ready);
            for(const phase of ['before','after']){await massStyle.evaluate((n,t)=>{n.textContent=t;},css(phase==='before'?out+'/before-mass-import.css':root+'/styles/mass-import.css'));await settle(empty);result.rows.push({kind:'real-preview-search-empty',locale,width,phase,measurement:await measure(empty)});}
            await context.close();
        }
        assert.equal(result.rows.length,16);for(const a of result.rows.filter(r=>r.phase==='after')){const before=result.rows.find(r=>r.phase==='before'&&r.kind===a.kind&&r.locale===a.locale&&r.width===a.width);assert.deepEqual(a.measurement,before.measurement,'Native shell and real search-empty frames and paint identical');}assert.ok(result.rows.some(r=>r.width===390&&r.kind==='workspace-shell'&&r.measurement.parts.some(p=>p.class.includes('__filters'))),'Actual narrow filter shell measured');
        assert.equal(result.errors.length, 0); result.passed = true;
    } catch (e) {
        result.failure = e.message;
        if (page && !page.isClosed()) await page.screenshot({path: out + '/failure.png', timeout: 10000}).catch(() => {});
    } finally {
        if (browser) await browser.close();
        if (!created && fs.existsSync(out + '/fixture-ids.json')) {
            const ids = JSON.parse(fs.readFileSync(out + '/fixture-ids.json'));
            const restored = fs.existsSync(out + '/fixture-restored.json') ? JSON.parse(fs.readFileSync(out + '/fixture-restored.json')) : {};
            created = !(restored.removed && restored.courseid === ids.courseid);
        }
        if (created) result.fixtureCleanup = JSON.parse(cp.execFileSync('<PHP_BINARY>', [out + '/fixture.php', 'cleanup'], {encoding: 'utf8'}));
        if (lease) {ps('Release-EasyEduResourceLease.ps1', ['-Resource', 'moodle51-perf', '-RunId', runId]); result.leaseReleased = true;}
        if(result.fixtureCleanup?.draftRemoved!==true){result.passed=false;result.failure='Own draft area was not removed';}
        fs.writeFileSync(out + '/native.json', JSON.stringify(result, null, 2));
        console.log(JSON.stringify({passed: result.passed, rows: result.rows.length, errors: result.errors.length, failure: result.failure, restored: result.fixtureCleanup, leaseReleased: result.leaseReleased}));
    }
})();
